args.Content:
/* ==========================================================================
   Grace Fellowship Church - Home Page Design System
   Professional, Production-Grade Polish with Centralized Design Tokens
   ========================================================================== */

@import url('../design-tokens.css');

:root {
  /* Brand mappings to Centralized Design Tokens */
  --navy-900: var(--color-primary-900);
  --navy-800: var(--color-primary-800);
  --navy-700: var(--color-primary-700);
  --navy-600: var(--color-primary-600);

  --blue-primary: var(--color-action);
  --blue-hover: var(--color-action-hover);
  --blue-light: var(--color-action-light);
  --blue-border: var(--color-action-border);

  --gold-accent: var(--color-gold-500);
  --gold-hover: var(--color-gold-600);
  --gold-light: var(--color-gold-100);

  /* Neutrals */
  --bg-white: var(--color-surface);
  --bg-page: var(--color-bg-page);
  --bg-gray-50: var(--color-surface-hover);
  --bg-gray-100: var(--color-surface-subtle);
  --border-light: var(--color-border);
  --border-subtle: var(--color-border-subtle);

  /* Typography Colors */
  --text-navy: var(--color-text-primary);
  --text-slate: var(--color-text-secondary);
  --text-muted: var(--color-text-muted);
  --text-light: var(--color-text-light);

  /* Shadows */
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);

  /* Radius */
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-pill: var(--radius-full);
}

/* Base Reset & Accessibility Standards */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-bg-page);
  color: var(--color-text-primary);
  line-height: var(--leading-normal);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
  transition: all var(--transition-fast);
}

button {
  font-family: inherit;
  border: none;
  outline: none;
  background: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Layout Containers */
.home-container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--container-pad);
}

.home-section {
  padding: 48px 0;
}

.section-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

.section-title-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
}

.section-title-icon {
  font-size: 1.35rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--color-gold-500);
}

.section-title-text {
  font-family: var(--font-sans);
  font-size: var(--text-2xl);
  font-weight: var(--weight-bold);
  color: var(--color-primary-800);
  letter-spacing: -0.015em;
  line-height: var(--leading-tight);
}

.section-view-all {
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  color: var(--color-action);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  transition: background-color var(--transition-fast), color var(--transition-fast);
}

.section-view-all:hover {
  color: var(--color-action-hover);
  background-color: var(--color-action-light);
}

/* ==========================================================================
   1. Floating Navigation Bar
   ========================================================================== */
.church-navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.97);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 1px 3px rgba(15, 30, 54, 0.05);
  border-bottom: 1px solid var(--color-border);
  transition: background var(--transition-base), box-shadow var(--transition-base);
}

.church-navbar.scrolled {
  box-shadow: 0 4px 20px rgba(15, 30, 54, 0.08);
}

.navbar-inner {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 12px var(--container-pad);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

/* Unified Brand Crest */
.nav-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  cursor: pointer;
}

.nav-brand-logo {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--color-primary-800);
  border: 1px solid rgba(197, 155, 39, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(15, 30, 54, 0.15);
  flex-shrink: 0;
  transition: transform var(--transition-fast);
}

.nav-brand:hover .nav-brand-logo {
  transform: scale(1.04);
}

.nav-cross-icon {
  font-size: 1.45rem;
  color: var(--color-gold-500);
  line-height: 1;
}

.nav-brand-text {
  display: flex;
  flex-direction: column;
}

.nav-church-name {
  font-family: var(--font-display);
  font-size: 1.125rem;
  font-weight: var(--weight-bold);
  color: var(--color-primary-800);
  letter-spacing: -0.01em;
  white-space: nowrap;
  line-height: 1.2;
}

.nav-church-tagline {
  font-family: var(--font-sans);
  font-size: 0.725rem;
  font-weight: var(--weight-medium);
  color: var(--color-text-muted);
  letter-spacing: 0.03em;
  white-space: nowrap;
  margin-top: 1px;
}

/* Nav Links */
.nav-links-desktop {
  display: flex;
  align-items: center;
  gap: 6px;
  list-style: none;
}

.nav-link-item {
  display: inline-block;
}

.nav-link-btn {
  padding: 8px 16px;
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: all var(--transition-fast);
  white-space: nowrap;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
}

.nav-link-btn:hover {
  color: var(--color-action);
  background-color: var(--color-surface-hover);
}

.nav-link-btn.active {
  background-color: var(--color-action);
  color: #ffffff;
  font-weight: var(--weight-semibold);
  box-shadow: 0 2px 8px rgba(0, 102, 204, 0.25);
}

.btn-nav-donate {
  padding: 8px 22px;
  border-radius: var(--radius-full);
  background-color: var(--color-action);
  color: #ffffff;
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  text-decoration: none;
  transition: all var(--transition-fast);
  box-shadow: 0 2px 8px rgba(0, 102, 204, 0.25);
  white-space: nowrap;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
}

.btn-nav-donate:hover {
  background-color: var(--color-action-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(0, 102, 204, 0.35);
}

.btn-nav-donate:active {
  transform: translateY(0);
}

/* Mobile Hamburger Toggle */
.hamburger-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  background: var(--color-surface-subtle);
  border: 1px solid var(--color-border);
  gap: 5px;
  cursor: pointer;
}

.hamburger-bar {
  width: 20px;
  height: 2px;
  background-color: var(--color-primary-800);
  border-radius: 2px;
  transition: all var(--transition-fast);
}

/* Mobile Drawer Menu */
.mobile-nav-drawer {
  display: none;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: 16px var(--container-pad) 24px var(--container-pad);
  box-shadow: var(--shadow-lg);
  animation: slideDown 0.2s ease-out;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.mobile-nav-drawer.open {
  display: block;
}

.mobile-nav-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mobile-nav-list a {
  display: block;
  padding: 12px 16px;
  font-size: var(--text-base);
  font-weight: var(--weight-semibold);
  color: var(--color-text-primary);
  border-radius: var(--radius-sm);
  min-height: var(--min-touch-target);
  display: flex;
  align-items: center;
}

.mobile-nav-list a.active {
  background: var(--color-action);
  color: #ffffff;
}

.mobile-nav-list a:hover:not(.active) {
  background: var(--color-surface-subtle);
}

/* ==========================================================================
   2. Hero Section
   ========================================================================== */
.hero-section {
  position: relative;
  min-height: 520px;
  background-size: cover;
  background-position: center center;
  display: flex;
  align-items: center;
  color: #ffffff;
  padding: 80px 0;
  overflow: hidden;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(10, 21, 38, 0.45) 0%,
    rgba(15, 30, 54, 0.72) 65%,
    rgba(15, 30, 54, 0.9) 100%
  );
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 820px;
}

.hero-welcome {
  font-family: var(--font-display);
  font-size: var(--text-xl);
  font-weight: var(--weight-semibold);
  color: var(--color-gold-400);
  margin-bottom: 8px;
  text-shadow: 0 2px 6px rgba(0,0,0,0.5);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.hero-title {
  font-family: var(--font-sans);
  font-size: var(--text-4xl);
  font-weight: var(--weight-extrabold);
  line-height: var(--leading-tight);
  color: #ffffff;
  margin-bottom: 16px;
  text-shadow: 0 3px 12px rgba(0,0,0,0.5);
  letter-spacing: -0.025em;
}

.hero-subtitle {
  font-size: var(--text-lg);
  font-weight: var(--weight-medium);
  color: rgba(255, 255, 255, 0.95);
  margin-bottom: 20px;
  line-height: var(--leading-relaxed);
  text-shadow: 0 1px 4px rgba(0,0,0,0.4);
}

.hero-verse {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: var(--text-base);
  color: rgba(255, 255, 255, 0.9);
  margin-bottom: 32px;
  line-height: var(--leading-relaxed);
  max-width: 680px;
  padding-left: 14px;
  border-left: 3px solid var(--color-gold-400);
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-hero-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 32px;
  border-radius: var(--radius-full);
  background-color: var(--color-action);
  color: #ffffff;
  font-size: var(--text-base);
  font-weight: var(--weight-bold);
  box-shadow: 0 4px 18px rgba(0, 102, 204, 0.45);
  transition: all var(--transition-fast);
  min-height: var(--min-touch-target);
}

.btn-hero-primary:hover {
  background-color: var(--color-action-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 22px rgba(0, 102, 204, 0.55);
}

.btn-hero-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  justify-content: center;
  padding: 13px 28px;
  border-radius: var(--radius-full);
  background: rgba(15, 30, 54, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.7);
  color: #ffffff;
  font-size: var(--text-base);
  font-weight: var(--weight-semibold);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: all var(--transition-fast);
  min-height: var(--min-touch-target);
}

.btn-hero-secondary:hover {
  background: rgba(255, 255, 255, 0.2);
  border-color: #ffffff;
  transform: translateY(-2px);
}

/* ==========================================================================
   3. Announcements Section (Refined Card Architecture)
   ========================================================================== */
.announcements-box {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-left: 4px solid var(--color-gold-500);
  border-radius: var(--radius-lg);
  padding: 28px 32px;
  margin-top: 32px;
  box-shadow: var(--shadow-card);
}

.announcements-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

.announcements-carousel-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  gap: 16px;
}

.carousel-arrow-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-surface);
  box-shadow: var(--shadow-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary-800);
  font-size: 1.2rem;
  border: 1px solid var(--color-border);
  cursor: pointer;
  z-index: 2;
  flex-shrink: 0;
  transition: all var(--transition-fast);
}

.carousel-arrow-btn:hover {
  background: var(--color-primary-800);
  color: #ffffff;
  border-color: var(--color-primary-800);
}

.announcements-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  width: 100%;
}

.announcement-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.announcement-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}

.announcement-banner-img {
  width: 100%;
  height: 170px;
  object-fit: cover;
  transition: transform var(--transition-smooth);
}

.announcement-card:hover .announcement-banner-img {
  transform: scale(1.03);
}

.announcement-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.announcement-tag {
  align-self: flex-start;
  font-size: var(--text-xs);
  font-weight: var(--weight-bold);
  padding: 4px 10px;
  border-radius: var(--radius-full);
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.announcement-tag.badge-youth {
  background: #fef3c7;
  color: #92400e;
}

.announcement-tag.badge-outreach {
  background: #ecfdf5;
  color: #065f46;
}

.announcement-tag.badge-fellowship {
  background: #eff6ff;
  color: #1e40af;
}

.announcement-card-title {
  font-size: 1.1rem;
  font-weight: var(--weight-bold);
  color: var(--color-primary-800);
  margin-bottom: 8px;
  line-height: var(--leading-snug);
}

.announcement-meta {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 16px;
}

.announcement-btn {
  align-self: flex-start;
  padding: 8px 18px;
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: var(--weight-bold);
  margin-top: auto;
  border: 1px solid var(--color-action);
  background: var(--color-surface);
  color: var(--color-action);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.announcement-btn:hover {
  background: var(--color-action);
  color: #ffffff;
}

/* ==========================================================================
   4. Verse of the Day Section
   ========================================================================== */
.votd-card {
  position: relative;
  background: linear-gradient(135deg, #ffffff 0%, #f8fafc 60%, #f0f7ff 100%);
  border: 1px solid var(--color-border);
  border-left: 5px solid var(--color-gold-500);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 28px 36px;
  gap: 28px;
  box-shadow: var(--shadow-card);
}

.votd-left-visual {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-shrink: 0;
}

.votd-bible-img {
  width: 140px;
  height: 100px;
  object-fit: cover;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
}

.votd-content {
  flex-grow: 1;
}

.votd-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.votd-header-icon {
  font-size: 1.25rem;
  color: var(--color-gold-500);
}

.votd-header-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: var(--weight-bold);
  color: var(--color-primary-800);
  letter-spacing: 0.02em;
}

.votd-text {
  font-family: var(--font-serif);
  font-size: 1.35rem;
  font-weight: var(--weight-medium);
  color: var(--color-primary-900);
  margin-bottom: 8px;
  line-height: 1.5;
}

.votd-reference {
  font-size: var(--text-sm);
  font-weight: var(--weight-bold);
  color: var(--color-action);
  letter-spacing: 0.02em;
}

.btn-votd-read {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  background-color: var(--color-action);
  color: #ffffff;
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(0, 102, 204, 0.25);
  transition: all var(--transition-fast);
  min-height: var(--min-touch-target);
}

.btn-votd-read:hover {
  background-color: var(--color-action-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(0, 102, 204, 0.35);
}

/* ==========================================================================
   5. Service Timings Section
   ========================================================================== */
.timings-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.timing-card {
  border-radius: var(--radius-md);
  padding: 22px 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  box-shadow: var(--shadow-xs);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.timing-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.timing-card.card-blue {
  border-left: 4px solid var(--color-action);
  background: linear-gradient(135deg, #ffffff 0%, var(--color-action-light) 100%);
}

.timing-card.card-peach {
  border-left: 4px solid var(--color-warning);
  background: linear-gradient(135deg, #ffffff 0%, var(--color-warning-bg) 100%);
}

.timing-card.card-purple {
  border-left: 4px solid #7c3aed;
  background: linear-gradient(135deg, #ffffff 0%, #faf5ff 100%);
}

.timing-card.card-green {
  border-left: 4px solid var(--color-success);
  background: linear-gradient(135deg, #ffffff 0%, var(--color-success-bg) 100%);
}

.timing-icon-badge {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.35rem;
  flex-shrink: 0;
}

.timing-icon-blue {
  background: rgba(0, 102, 204, 0.12);
  color: var(--color-action);
}

.timing-icon-peach {
  background: rgba(217, 119, 6, 0.12);
  color: var(--color-warning);
}

.timing-icon-purple {
  background: rgba(124, 58, 237, 0.12);
  color: #7c3aed;
}

.timing-icon-green {
  background: rgba(5, 150, 105, 0.12);
  color: var(--color-success);
}

.timing-info {
  display: flex;
  flex-direction: column;
}

.timing-title {
  font-size: var(--text-base);
  font-weight: var(--weight-bold);
  color: var(--color-primary-800);
  margin-bottom: 3px;
}

.timing-hours {
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  color: var(--color-text-secondary);
  margin-bottom: 2px;
}

.timing-subtitle {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
}

/* ==========================================================================
   6. Latest Sermons Section
   ========================================================================== */
.sermons-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.sermon-video-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  cursor: pointer;
}

.sermon-video-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}

.sermon-thumb-box {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: var(--color-primary-950);
}

.sermon-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-smooth);
}

.sermon-video-card:hover .sermon-thumb-img {
  transform: scale(1.05);
}

.sermon-duration-tag {
  position: absolute;
  bottom: 8px;
  right: 8px;
  background: rgba(0, 0, 0, 0.82);
  color: #ffffff;
  font-size: var(--text-xs);
  font-weight: var(--weight-bold);
  padding: 3px 8px;
  border-radius: var(--radius-xs);
  letter-spacing: 0.03em;
}

.sermon-play-overlay {
  position: absolute;
  inset: 0;
  background: rgba(15, 30, 54, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity var(--transition-fast);
}

.sermon-video-card:hover .sermon-play-overlay {
  opacity: 1;
}

.sermon-play-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-action);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.35);
}

.sermon-info-box {
  padding: 16px;
  display: flex;
  flex-direction: column;
}

.sermon-card-title {
  font-size: 1.05rem;
  font-weight: var(--weight-bold);
  color: var(--color-primary-800);
  margin-bottom: 6px;
  line-height: var(--leading-snug);
}

.sermon-card-speaker {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  font-weight: var(--weight-medium);
  margin-bottom: 3px;
}

.sermon-card-date {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
}

/* ==========================================================================
   7. Upcoming Events Section
   ========================================================================== */
.events-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.event-item-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.event-item-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.event-thumb-wrapper {
  width: 150px;
  height: 120px;
  flex-shrink: 0;
  overflow: hidden;
}

.event-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-smooth);
}

.event-item-card:hover .event-thumb-img {
  transform: scale(1.05);
}

.event-card-details {
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.event-heading {
  font-size: 1.05rem;
  font-weight: var(--weight-bold);
  color: var(--color-primary-800);
  margin-bottom: 6px;
  line-height: var(--leading-snug);
}

.event-meta-line {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 3px;
}

.btn-event-action {
  align-self: flex-start;
  margin-top: 10px;
  padding: 6px 16px;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-action);
  background: var(--color-surface);
  color: var(--color-action);
  font-size: var(--text-xs);
  font-weight: var(--weight-bold);
  transition: all var(--transition-fast);
}

.btn-event-action:hover {
  background: var(--color-action);
  color: #ffffff;
}

/* ==========================================================================
   8. Our Ministries Section
   ========================================================================== */
.ministries-row {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 20px;
}

.ministry-unit-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform var(--transition-base);
  cursor: pointer;
}

.ministry-unit-card:hover {
  transform: translateY(-4px);
}

.ministry-photo-frame {
  width: 100%;
  aspect-ratio: 16 / 11;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
  margin-bottom: 12px;
}

.ministry-photo {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-smooth);
}

.ministry-unit-card:hover .ministry-photo {
  transform: scale(1.06);
}

.ministry-label {
  font-size: 0.925rem;
  font-weight: var(--weight-bold);
  color: var(--color-primary-800);
  line-height: var(--leading-snug);
}

/* ==========================================================================
   9. Visit Our Church Section
   ========================================================================== */
.visit-church-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr 1.3fr;
  gap: 28px;
  align-items: center;
}

.church-exterior-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border);
}

.church-exterior-img {
  width: 100%;
  height: 220px;
  object-fit: cover;
}

.church-contact-info {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.contact-info-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  line-height: var(--leading-relaxed);
}

.contact-info-icon {
  font-size: 1.15rem;
  color: var(--color-gold-500);
  flex-shrink: 0;
  margin-top: 2px;
}

.church-social-icons {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 8px;
}

.social-circle-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-size: 1rem;
  transition: transform var(--transition-fast), opacity var(--transition-fast);
}

.social-circle-btn:hover {
  transform: scale(1.1);
  opacity: 0.9;
}

.social-circle-btn.fb { background: #1877f2; }
.social-circle-btn.yt { background: #ff0000; }
.social-circle-btn.ig { background: radial-gradient(circle at 30% 107%, #fdf497 0%, #fdf497 5%, #fd5949 45%, #d6249f 60%, #285aeb 90%); }
.social-circle-btn.wa { background: #25d366; }

/* Map Card */
.church-map-card {
  position: relative;
  height: 220px;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  background: var(--color-surface-subtle);
}

.map-svg-canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.btn-view-maps {
  position: absolute;
  top: 12px;
  right: 12px;
  background-color: var(--color-action);
  color: #ffffff;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: var(--text-xs);
  font-weight: var(--weight-bold);
  box-shadow: 0 2px 8px rgba(0,0,0,0.18);
  transition: all var(--transition-fast);
  min-height: 34px;
  display: inline-flex;
  align-items: center;
}

.btn-view-maps:hover {
  background-color: var(--color-action-hover);
}

.map-zoom-controls {
  position: absolute;
  bottom: 12px;
  right: 12px;
  display: flex;
  flex-direction: column;
  background: #ffffff;
  border-radius: var(--radius-xs);
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  overflow: hidden;
  border: 1px solid var(--color-border);
}

.map-zoom-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.15rem;
  font-weight: var(--weight-bold);
  color: var(--color-text-secondary);
  background: #ffffff;
  cursor: pointer;
}

.map-zoom-btn:hover {
  background: var(--color-surface-subtle);
}

.map-zoom-btn:first-child {
  border-bottom: 1px solid var(--color-border);
}

/* ==========================================================================
   10. Footer Section
   ========================================================================== */
.church-footer {
  background-color: var(--color-primary-950);
  color: #ffffff;
  padding: 56px 0 28px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.footer-main-grid {
  display: grid;
  grid-template-columns: 1.4fr 1.2fr 0.9fr 1fr;
  gap: 40px;
  padding-bottom: 36px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
}

.footer-cross {
  font-size: 1.6rem;
  color: var(--color-gold-400);
}

.footer-church-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: var(--weight-bold);
  color: #ffffff;
  letter-spacing: 0.02em;
}

.footer-tagline {
  font-size: var(--text-xs);
  color: rgba(255, 255, 255, 0.65);
}

.footer-brand-desc {
  font-size: var(--text-sm);
  line-height: var(--leading-relaxed);
  color: rgba(255, 255, 255, 0.75);
  margin-bottom: 20px;
}

.footer-section-title {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: var(--weight-bold);
  color: #ffffff;
  margin-bottom: 16px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.footer-visit-info {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.visit-info-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: var(--text-sm);
  line-height: var(--leading-normal);
  color: rgba(255, 255, 255, 0.85);
}

.visit-info-item strong {
  color: #ffffff;
}

.visit-icon {
  font-size: 1.05rem;
  color: var(--color-gold-400);
  flex-shrink: 0;
  margin-top: 1px;
}

.footer-directions-btn {
  display: inline-block;
  margin-top: 4px;
  color: var(--color-action-hover);
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  text-decoration: none;
  transition: color var(--transition-fast);
}

.footer-directions-btn:hover {
  color: #ffffff;
  text-decoration: underline;
}

.footer-nav-links-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-nav-link {
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: rgba(255, 255, 255, 0.8);
  transition: color var(--transition-fast), transform var(--transition-fast);
  text-decoration: none;
}

.footer-nav-link:hover {
  color: #ffffff;
  transform: translateX(3px);
}

.footer-hours-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: var(--text-sm);
  color: rgba(255, 255, 255, 0.8);
}

.footer-hours-list li strong {
  color: #ffffff;
}

.footer-social-links {
  display: flex;
  align-items: center;
  gap: 10px;
}

.footer-social-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-size: 0.95rem;
  background: rgba(255, 255, 255, 0.12);
  transition: background var(--transition-fast), transform var(--transition-fast);
  text-decoration: none;
}

.footer-social-icon:hover {
  background: var(--color-action);
  transform: translateY(-2px);
}

.footer-bottom-copy {
  margin-top: 28px;
  text-align: center;
  font-size: var(--text-xs);
  color: rgba(255, 255, 255, 0.55);
}

/* ==========================================================================
   Responsive Breakpoints
   Desktop (>1040px)
   Tablet (768px - 1040px)
   Mobile (<768px)
   ========================================================================== */
@media (max-width: 1040px) {
  .nav-links-desktop {
    display: none;
  }
  .hamburger-toggle {
    display: flex;
  }
  .timings-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .sermons-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .ministries-row {
    grid-template-columns: repeat(3, 1fr);
    row-gap: 24px;
  }
  .visit-church-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .footer-main-grid {
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }
}

@media (max-width: 768px) {
  .home-section {
    padding: 36px 0;
  }
  .hero-section {
    min-height: 440px;
    padding: 60px 0;
  }
  .hero-title {
    font-size: 2.25rem;
  }
  .hero-welcome {
    font-size: 1.15rem;
  }
  .hero-subtitle {
    font-size: 1rem;
  }
  .announcements-box {
    padding: 20px 16px;
  }
  .announcements-carousel-wrapper {
    gap: 8px;
  }
  .carousel-arrow-btn {
    display: none;
  }
  .announcements-grid {
    grid-template-columns: 1fr;
    gap: 18px;
  }
  .announcement-banner-img {
    height: 160px;
  }
  .votd-card {
    flex-direction: column;
    align-items: stretch;
    padding: 22px 20px;
  }
  .votd-left-visual {
    width: 100%;
  }
  .votd-bible-img {
    width: 100%;
    height: 140px;
  }
  .btn-votd-read {
    align-self: flex-start;
  }
  .events-grid {
    grid-template-columns: 1fr;
  }
  .event-item-card {
    flex-direction: column;
    align-items: stretch;
  }
  .event-thumb-wrapper {
    width: 100%;
    height: 160px;
  }
  .footer-main-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}

@media (max-width: 480px) {
  .nav-church-name {
    font-size: 1rem;
  }
  .nav-church-tagline {
    display: none;
  }
  .home-container {
    padding: 0 16px;
  }
  .timings-grid {
    grid-template-columns: 1fr;
  }
  .sermons-grid {
    grid-template-columns: 1fr;
  }
  .ministries-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .hero-actions {
    flex-direction: column;
    width: 100%;
  }
  .btn-hero-primary, .btn-hero-secondary {
    width: 100%;
    text-align: center;
  }
}

