function Announcements() {
  const [startIndex, setStartIndex] = React.useState(0);

  const announcementsData = [
    {
      id: 1,
      title: "YOUTH CONFERENCE 2024",
      subtitle: "Rise Up & Shine Forth - Ignite Your Faith",
      date: "Aug 15 – 17, 2024",
