const fs = require('fs');
const path = require('path');

const projectRoot = 'C:/my projects/Church App';
const frontendDir = path.join(projectRoot, 'frontend');

console.log('=== Comprehensive UI/UX & Asset Audit ===');

const files = [
  'design-tokens.css',
  'index.html',
  'home/home.css',
  'bible/index.html',
  'bible/bible-react.css',
  'prayer-request/index.html',
  'prayer-request/prayer-request.css',
  'prayer-request/admin.html'
];

let allOk = true;

// 1. Check all critical files exist
for (const rel of files) {
  const p = path.join(frontendDir, rel);
  if (!fs.existsSync(p)) {
    console.error('MISSING:', rel);
    allOk = false;
  } else {
    const stat = fs.statSync(p);
    console.log(`[FILE] ${rel.padEnd(35)} ${stat.size} bytes`);
  }
}

// 2. Validate Design Tokens definitions
const tokensContent = fs.readFileSync(path.join(frontendDir, 'design-tokens.css'), 'utf8');
const definedTokens = new Set();
const tokenRegex = /--[a-zA-Z0-9_-]+(?=:)/g;
let tm;
while ((tm = tokenRegex.exec(tokensContent)) !== null) {
  definedTokens.add(tm[0]);
}
console.log(`\n[TOKENS] Master Design System contains ${definedTokens.size} CSS variables/tokens.`);

// 3. Check CSS Imports
const cssFiles = [
  path.join(frontendDir, 'home/home.css'),
  path.join(frontendDir, 'bible/bible-react.css'),
  path.join(frontendDir, 'prayer-request/prayer-request.css')
];

for (const cssFile of cssFiles) {
  const rel = path.relative(frontendDir, cssFile);
  const content = fs.readFileSync(cssFile, 'utf8');
  if (content.includes('design-tokens.css')) {
    console.log(`[IMPORT OK] ${rel} successfully imports master design-tokens.css`);
  } else {
    console.error(`[IMPORT MISSING] ${rel} does not import design-tokens.css`);
    allOk = false;
  }
}

// 4. Check HTML links
const htmlFiles = [
  path.join(frontendDir, 'index.html'),
  path.join(frontendDir, 'bible/index.html'),
  path.join(frontendDir, 'prayer-request/index.html'),
  path.join(frontendDir, 'prayer-request/admin.html')
];

for (const htmlFile of htmlFiles) {
  const rel = path.relative(frontendDir, htmlFile);
  const content = fs.readFileSync(htmlFile, 'utf8');
  if (content.includes('design-tokens.css')) {
    console.log(`[LINK OK] ${rel} links to design-tokens.css`);
  } else {
    console.error(`[LINK MISSING] ${rel} does not link to design-tokens.css`);
    allOk = false;
  }
}

// 5. Check Assets and Images referenced across all pages
for (const htmlFile of htmlFiles) {
  const content = fs.readFileSync(htmlFile, 'utf8');
  const dir = path.dirname(htmlFile);
  const imgRegex = /src=["']([^"']+\.(jpg|png|svg))["']/g;
  let m;
  while ((m = imgRegex.exec(content)) !== null) {
    const relPath = m[1];
    if (!relPath.startsWith('http') && !relPath.startsWith('data:')) {
      const resolved = path.resolve(dir, relPath);
      if (fs.existsSync(resolved)) {
        // OK
      } else {
        console.error(`[BROKEN ASSET] In ${path.basename(htmlFile)}: ${relPath} not found`);
        allOk = false;
      }
    }
  }
}

console.log('\n=== Distribution Bundle Build Verification ===');
require(path.join(projectRoot, 'scripts/build.js'));

const distTokens = path.join(projectRoot, 'dist/design-tokens.css');
if (fs.existsSync(distTokens)) {
  console.log('[DIST OK] dist/design-tokens.css packaged successfully.');
} else {
  console.error('[DIST FAIL] dist/design-tokens.css not found.');
  allOk = false;
}

console.log(`\n=== Verification Completed: ${allOk ? 'ALL CHECKS PASSED PERFECTLY' : 'ERRORS FOUND'} ===`);
process.exit(allOk ? 0 : 1);

