55: async function request(endpoint, options = {}) {
56:   const token = authService.getToken();
57:   const headers = {
58:     ...(options.headers || {}),
59:   };
60: 
61:   // Only add json header if body is not FormData
62:   if (!(options.body instanceof FormData) && !headers['Content-Type']) {
63:     headers['Content-Type'] = 'application/json';
64:   }
65: 
66:   if (token) {
67:     headers['Authorization'] = `Bearer ${token}`;
68:   }
69: 
70:   const response = await fetch(endpoint, {
71:     ...options,
72:     headers,
73:   });
74: 
75:   if (response.status === 401) {
76:     authService.clearSession();
77:     window.dispatchEvent(new CustomEvent('auth:expired'));
78:     throw new Error('Your session has expired. Please sign in again.');
79:   }
80: 
81:   if (!response.ok) {
82:     let errorDetail = `Request failed (${response.status})`;
83:     try {
84:       const errJson = await response.json();
85:       errorDetail = errJson.detail || errJson.message || errorDetail;
86:     } catch {
87:       // ignore
88:     }
89:     throw new Error(errorDetail);
90:   }
91: 
92:   return response.json();
93: }
