  --status-pending-border: #fde68a;

  --status-prayed-bg: #dcfce7;
  --status-prayed-text: #16a34a;
  --status-prayed-border: #bbf7d0;

  --status-archived-bg: #f1f5f9;
  --status-archived-text: #475569;
  --status-archived-border: #e2e8f0;

  --status-danger-bg: #fee2e2;
  --status-danger-text: #ef4444;

  /* Category Badges */
  --cat-health-bg: #fdf2f8;
  --cat-health-text: #e11d48;
  --cat-health-border: #fecdd3;

  --cat-employment-bg: #eff6ff;
  --cat-employment-text: #2563eb;
  --cat-employment-border: #bfdbfe;

  --cat-family-bg: #fffbeb;
  --cat-family-text: #d97706;
  --cat-family-border: #fde68a;

  --cat-education-bg: #faf5ff;
  --cat-education-text: #9333ea;
  --cat-education-border: #e9d5ff;

  --cat-spiritual-bg: #eef2ff;
  --cat-spiritual-text: #4f46e5;
  --cat-spiritual-border: #c7d2fe;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -2px rgba(0, 0, 0, 0.04);
  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.04), 0 1px 2px rgba(0, 0, 0, 0.02);
}

/* Reset & Global */
*, *::before, *::after {
  box-sizing: border-box;
