  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* Layout */
.admin-layout {
  display: flex;
  min-height: 100vh;
  background-color: var(--admin-bg);
}

.admin-main {
  flex: 1;
  margin-left: var(--sidebar-width);
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.admin-content {
  padding: 24px 32px 40px;
  max-width: 1560px;
  width: 100%;
}

