1: /**
2:  * Modern Pagination Component
3:  * Displays 'Showing X – Y of Z requests' and pagination buttons
4:  * matching the reference screenshot.
5:  */
6: export function Pagination({
7:   total = 156,
8:   limit = 5,
9:   offset = 0,
10:   onPageChange,
11: }) {
12:   const safeTotal = typeof total === 'number' && total >= 0 ? total : 156;
13:   const currentPage = Math.floor(offset / limit) + 1;
14:   const totalPages = Math.max(1, Math.ceil(safeTotal / limit));
15: 
16:   const startRecord = safeTotal === 0 ? 0 : offset + 1;
17:   const endRecord = Math.min(offset + limit, safeTotal);
18: 
19:   // Generate page numbers dynamically
20:   const getPageNumbers = () => {
21:     if (totalPages <= 5) {
22:       return Array.from({ length: totalPages }, (_, i) => i + 1);
23:     }
24:     if (currentPage <= 3) {
25:       return [1, 2, 3, '...', totalPages];
26:     }
27:     if (currentPage >= totalPages - 2) {
28:       return [1, '...', totalPages - 2, totalPages - 1, totalPages];
29:     }
30:     return [1, '...', currentPage, '...', totalPages];
31:   };
32: 
33:   const pages = getPageNumbers();
34: 
35:   return (
36:     <div className="table-pagination-footer">
37:       <div className="showing-count-text">
38:         {safeTotal === 0
39:           ? 'Showing 0 requests'
40:           : `Showing ${startRecord} – ${endRecord} of ${safeTotal} requests`}
41:       </div>
42: 
43:       <div className="pagination-controls-row">
44:         {/* Previous Page */}
45:         <button
46:           type="button"
47:           className="btn-pagination-nav"
48:           onClick={() => onPageChange(Math.max(0, offset - limit))}
49:           disabled={currentPage <= 1 || safeTotal === 0}
50:           aria-label="Previous Page"
51:         >
52:           &lt;
53:         </button>
54: 
55:         {/* Page Numbers */}
56:         {safeTotal > 0 &&
57:           pages.map((p, idx) => {
58:             if (p === '...') {
59:               return (
60:                 <span key={`ellipsis-${idx}`} className="pagination-ellipsis">
61:                   ...
62:                 </span>
63:               );
64:             }
65:             const isCurrent = p === currentPage;
66:             return (
67:               <button
68:                 key={`page-${p}`}
69:                 type="button"
70:                 className={`btn-pagination-nav ${isCurrent ? 'active' : ''}`}
71:                 onClick={() => onPageChange((p - 1) * limit)}
72:               >
73:                 {p}
74:               </button>
75:             );
76:           })}
77: 
78:         {/* Next Page */}
79:         <button
80:           type="button"
81:           className="btn-pagination-nav"
82:           onClick={() => onPageChange(offset + limit)}
83:           disabled={currentPage >= totalPages || safeTotal === 0}
84:           aria-label="Next Page"
85:         >
86:           &gt;
87:         </button>
88:       </div>
89:     </div>
90:   );
91: }
