/* ==========================================================================
   Admin Login Canvas & Authentication Card
   ========================================================================== */

.login-canvas {
  min-height: 100vh;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 20%, #0d1e38 0%, #060e1a 100%);
  padding: 32px 16px;
  box-sizing: border-box;
  font-family: 'Plus Jakarta Sans', sans-serif;
  position: relative;
}

.login-back-link {
  position: absolute;
  top: 24px;
  left: 24px;
  color: #94a3b8;
  font-size: 0.875rem;
  font-weight: 500;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: all 0.18s ease;
}

.login-back-link:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.2);
  transform: translateX(-2px);
}

.login-card {
  width: 100%;
  max-width: 440px;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(255, 255, 255, 0.08);
  padding: 36px 32px 32px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  animation: loginCardFadeIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@keyframes loginCardFadeIn {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.login-brand-header {
  text-align: center;
  margin-bottom: 24px;
}

.login-crest {
  width: 52px;
  height: 52px;
  margin: 0 auto 14px;
  border-radius: 14px;
  background: linear-gradient(135deg, #0b1a30 0%, #1e3a66 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #c59b27;
  font-size: 1.85rem;
  box-shadow: 0 4px 12px rgba(11, 26, 48, 0.25);
  border: 1px solid rgba(197, 155, 39, 0.3);
}

.login-title {
  font-size: 1.45rem;
  font-weight: 800;
  color: #0b1a30;
  letter-spacing: -0.02em;
  margin: 0 0 6px;
}

.login-subtitle {
  font-size: 0.85rem;
  color: #64748b;
  margin: 0;
  font-weight: 500;
  line-height: 1.4;
}

.login-error-banner {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  color: #991b1b;
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 20px;
  font-size: 0.85rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 10px;
  line-height: 1.35;
}

.login-error-icon {
  flex-shrink: 0;
  color: #dc2626;
}

.login-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.password-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.password-input-wrap .form-input {
  padding-right: 42px;
  width: 100%;
}

.btn-toggle-password {
  position: absolute;
  right: 10px;
  background: transparent;
  border: none;
  color: #64748b;
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
