        </div>
      </div>

      {/* Two-Column Lower Layout: Recent Activities & Needs Attention Prayers */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(360px, 1fr))', gap: '20px' }}>
        {/* Left Column: Recent Audit Log Feed */}
