                    >
                      {log.action || 'ACTIVITY'}
                    </span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <p style={{ margin: 0, fontSize: '0.825rem', fontWeight: 600, color: '#1e293b' }}>
