                        {req.is_anonymous ? 'Anonymous Believer' : (req.name || 'Anonymous')}
                      </span>
                      {req.category && (
                        <span style={{ fontSize: '0.72rem', padding: '2px 8px', borderRadius: '9999px', background: '#fee2e2', color: '#dc2626', fontWeight: 700 }}>
