                    </div>
                    <span style={{ fontSize: '0.75rem', color: '#64748b' }}>
                      {formatDate(req.created_at)}
                    </span>
                  </div>

                  <p
                    style={{
                      margin: 0,
                      fontSize: '0.825rem',
                      color: '#334155',
                      lineHeight: 1.5,
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      display: '-webkit-box',
                      WebkitLineClamp: 2,
                      WebkitBoxOrient: 'vertical',
