        <h3 style={{ fontSize: '1.05rem', fontWeight: 700, color: '#0f172a', borderBottom: '1px solid #e2e8f0', paddingBottom: '12px' }}>
          Reader Defaults & Translation Selection
        </h3>

        <div className="form-group" style={{ maxWidth: '420px' }}>
