  cursor: pointer;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.gallery-media-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 24px rgba(15, 30, 54, 0.08);
}

.gallery-thumb-container {
  height: 200px;
  position: relative;
  overflow: hidden;
  background: #0f1e36;
}

.gallery-thumb-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-base);
}

.gallery-media-card:hover .gallery-thumb-img {
  transform: scale(1.04);
}

.gallery-card-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: rgba(15, 23, 42, 0.85);
  color: #ffffff;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: var(--weight-semibold);
  backdrop-filter: blur(4px);
}

.gallery-card-type {
  position: absolute;
  top: 10px;
  right: 10px;
  background: var(--color-action);
  color: #ffffff;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: var(--weight-semibold);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.gallery-body-box {
  padding: 14px 16px;
}

.gallery-item-title {
  font-size: var(--text-sm);
  font-weight: var(--weight-bold);
  color: var(--color-text-primary);
  margin-bottom: 4px;
}

.gallery-item-caption {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
  line-height: 1.4;
}

/* ==========================================================================
   13. Donate Modal & Online Giving Styles
   ========================================================================== */
.modal-backdrop-church {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.65);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.donate-modal-card {
  width: 100%;
  max-width: 580px;
  background: #ffffff;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  box-shadow: 0 20px 40px -10px rgba(15, 30, 54, 0.25);
  overflow: hidden;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
}

.donate-modal-header {
  padding: 20px 24px;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #f8fafc;
}

.donate-header-title {
  font-size: var(--text-lg);
  font-weight: var(--weight-extrabold);
  color: var(--color-primary-800);
}

.donate-header-sub {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
  margin-top: 2px;
}

.donate-modal-body {
  padding: 24px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.donate-scripture-box {
  padding: 14px 16px;
  background: #fffdf5;
  border-left: 3px solid var(--color-accent);
  border-radius: var(--radius-sm);
  font-family: var(--font-serif);
  font-style: italic;
  font-size: var(--text-sm);
  color: #78350f;
  line-height: var(--leading-relaxed);
}

.giving-purposes-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.giving-purpose-btn {
  padding: 12px 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background: #f8fafc;
  text-align: center;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.giving-purpose-btn.active {
  border-color: var(--color-primary-800);
  background: var(--color-primary-800);
  color: #ffffff;
}

.giving-purpose-btn .purpose-title {
  font-size: var(--text-xs);
  font-weight: var(--weight-bold);
  display: block;
}

.bank-details-card {
  background: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 16px;
}

.bank-detail-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid #e2e8f0;
  font-size: var(--text-sm);
}

.bank-detail-row:last-child {
  border-bottom: none;
}

.bank-label {
  color: var(--color-text-muted);
  font-weight: var(--weight-medium);
}

.bank-value {
  color: var(--color-text-primary);
  font-weight: var(--weight-bold);
  font-family: monospace;
}

.btn-copy-tag {
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  background: #e2e8f0;
  color: var(--color-primary-800);
  font-size: 0.75rem;
  font-weight: var(--weight-bold);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.btn-copy-tag:hover {
  background: #cbd5e1;
}

.btn-modal-close-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  background: #e2e8f0;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.btn-modal-close-icon:hover {
  background: #cbd5e1;
  color: var(--color-text-primary);
}

/* Lightbox Modal */
.lightbox-modal-content {
  position: relative;
  max-width: 800px;
  width: 100%;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: #000000;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
}

.lightbox-img {
  width: 100%;
  max-height: 75vh;
  object-fit: contain;
  display: block;
}

.lightbox-caption-bar {
  padding: 16px 20px;
  background: #0f172a;
  color: #ffffff;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Responsive adjustments for new sections */
@media (max-width: 900px) {
  .about-intro-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 600px) {
  .giving-purposes-grid {
    grid-template-columns: 1fr;
  }
  .about-pillars-grid {
    grid-template-columns: 1fr;
  }
}

