/* ==========================================================================
   About Component - Grace Fellowship Church
   Church history, doctrinal pillars, core beliefs, and pastoral profile
   Dynamically integrated with Church CMS API.
   ========================================================================== */

function About({ data }) {
  const headline = data?.headline || "Worship • Grow • Serve • Share";
  const subheadline = data?.subheadline || "Rooted in scripture, growing in grace, and reaching our community with God's unconditional love.";
  const history = data?.church_history || "Founded with a sacred vision to worship Almighty God in spirit and truth, Grace Fellowship Church has stood as a beacon of Christian hope and community service. What began as a humble prayer group has grown into a vibrant congregation dedicated to sound biblical teaching, loving discipleship, and Christ-centered worship across generations.";
  const pastorName = data?.lead_pastor_name || "Ps. John Samuel";
  const pastorTitle = data?.lead_pastor_title || "Lead & Senior Pastor";
  const pastorBio = data?.lead_pastor_bio || "Serving Grace Fellowship Church with a pastoral heart, teaching the life-transforming Word of God with clarity and compassion. Dedicated to mentoring leaders and nurturing every member in faith.";

  const formatMedia = (url) => {
    if (!url) return "home/assets/sermon_pastor.jpg";
    if (url.startsWith("http://") || url.startsWith("https://") || url.startsWith("data:")) return url;
    return url.startsWith("/") ? url.slice(1) : url;
  };

  const pastorImage = formatMedia(data?.lead_pastor_image);

  const pillars = [
    {
      title: "Biblical Truth",
      desc: "Unwavering commitment to the inspired Word of God as our ultimate guide for faith, daily life, and salvation in Jesus Christ.",
      icon: (
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z" />
          <path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z" />
        </svg>
      )
    },
