/* ==========================================================================
   Navbar Component - Grace Fellowship Church
   Fixed floating navigation bar with mobile responsive drawer
   Dynamically integrated with Church CMS API.
   ========================================================================== */

function Navbar({ activeSection = "home", onNavigate, onOpenDonate, data }) {
  const [isScrolled, setIsScrolled] = React.useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);

  React.useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const churchName = data?.church_name || "Grace Fellowship Church";
  const churchTagline = data?.church_tagline || "Worship • Grow • Serve • Share";

  const navItems = [
    { id: "home", label: "Home", href: "#home" },
    { id: "about", label: "About", href: "#about" },
    { id: "service-timings", label: "Services", href: "#service-timings" },
    { id: "sermons", label: "Sermons", href: "#sermons" },
    { id: "events", label: "Events", href: "#events" },
    { id: "ministries", label: "Ministries", href: "#ministries" },
    { id: "gallery", label: "Gallery", href: "#gallery" },
    { id: "bible", label: "Bible", href: "bible/index.html" },
    { id: "prayer", label: "Prayer", href: "prayer-request/index.html" },
    { id: "contact", label: "Contact", href: "#contact" },
  ];

  const handleLinkClick = (id, href, e) => {
    if (href.startsWith("#")) {
      e.preventDefault();
      setMobileMenuOpen(false);
      if (onNavigate) onNavigate(id);
      const target = document.getElementById(href.substring(1));
      if (target) {
        target.scrollIntoView({ behavior: "smooth" });
      }
    }
  };

  return (
    <header className={`church-navbar ${isScrolled ? "scrolled" : ""}`}>
      <div className="navbar-inner">
        {/* Brand */}
        <a href="#home" className="nav-brand" onClick={(e) => handleLinkClick("home", "#home", e)}>
          <div className="nav-brand-logo">
            {data?.logo_url ? (
              <img src={data.logo_url} alt="" style={{ width: "24px", height: "24px", objectFit: "contain" }} />
            ) : (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className="nav-cross-icon">
                <path d="M12 2v20M7 8h10" />
              </svg>
            )}
          </div>
          <div className="nav-brand-text">
            <span className="nav-church-name">{churchName}</span>
            <span className="nav-church-tagline">{churchTagline}</span>
          </div>
        </a>

        {/* Desktop Navigation */}
        <nav className="nav-links-desktop" aria-label="Main Navigation">
          {navItems.map((item) => (
            <li key={item.id} className="nav-link-item">
              <a
                href={item.href}
                className={`nav-link-btn ${activeSection === item.id ? "active" : ""}`}
                onClick={(e) => handleLinkClick(item.id, item.href, e)}
              >
                {item.label}
              </a>
            </li>
          ))}

          {/* Online Giving Trigger */}
          <button
            type="button"
            className="btn-nav-donate"
            onClick={onOpenDonate}
            title="Online Tithes & Giving"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z" />
            </svg>
            <span>Give</span>
          </button>
        </nav>

        {/* Mobile Hamburger Button */}
        <button
          type="button"
          className="hamburger-toggle"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Toggle navigation menu"
          aria-expanded={mobileMenuOpen}
        >
          <span className="hamburger-bar" />
          <span className="hamburger-bar" />
          <span className="hamburger-bar" />
        </button>
      </div>

      {/* Mobile Drawer */}
      <div className={`mobile-nav-drawer ${mobileMenuOpen ? "open" : ""}`} aria-hidden={!mobileMenuOpen}>
        <ul className="mobile-nav-list">
          {navItems.map((item) => (
            <li key={item.id}>
              <a
                href={item.href}
                className={activeSection === item.id ? "active" : ""}
                onClick={(e) => handleLinkClick(item.id, item.href, e)}
              >
                {item.label}
              </a>
            </li>
          ))}
          <li style={{ marginTop: "12px" }}>
            <button
              type="button"
              className="btn-nav-donate"
              style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "8px", width: "100%", padding: "12px" }}
              onClick={() => {
                setMobileMenuOpen(false);
                if (onOpenDonate) onOpenDonate();
              }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                <path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z" />
              </svg>
              <span>Give Online</span>
            </button>
          </li>
        </ul>
      </div>
    </header>
  );
}

