/* ==========================================================================
   Ministries Component - Grace Fellowship Church
   Ministry grid with photos, fellowship groups, and outreach descriptions
   Dynamically integrated with Church CMS API. Zero emojis, pure SVGs.
   ========================================================================== */

function Ministries({ data }) {
  const formatMedia = (url) => {
    if (!url) return "home/assets/children_ministry.jpg";
    if (url.startsWith("http://") || url.startsWith("https://") || url.startsWith("data:")) return url;
    return url.startsWith("/") ? url.slice(1) : url;
  };

  const fallbackMinistries = [
    {
      id: 1,
      name: "Children's Ministry",
      photo: "home/assets/children_ministry.jpg",
      description: "Nurturing young hearts with biblical foundation, crafts, and songs."
    },
    {
      id: 2,
      name: "Youth Ministry",
      photo: "home/assets/youth_conference.jpg",
      description: "Empowering teens and young adults to stand bold for Christ."
    },
    {
      id: 3,
      name: "Women's Ministry",
      photo: "home/assets/womens_fellowship.jpg",
      description: "Encouraging sisters in faith, discipleship, and prayer fellowship."
    },
    {
      id: 4,
      name: "Men's Ministry",
      photo: "home/assets/fellowship_service.jpg",
      description: "Building strong godly fathers, husbands, and leaders in Christ."
    },
    {
      id: 5,
      name: "Prayer Ministry",
      photo: "home/assets/prayer_hands.jpg",
      description: "Faithful intercession for our church, community, and global needs."
    },
    {
      id: 6,
      name: "Outreach Ministry",
      photo: "home/assets/worship_service.jpg",
      description: "Sharing the love of Christ through local and regional benevolence."
    }
  ];

  const ministryList = (Array.isArray(data) && data.length > 0)
    ? data.map((m) => ({
        id: m.id,
        name: m.name,
        photo: formatMedia(m.photo),
        description: m.short_description || m.full_description,
      }))
    : fallbackMinistries;

  return (
    <section id="ministries" className="home-container home-section">
      <div className="section-header-row">
        <div className="section-title-wrap">
          <span className="section-title-icon" aria-hidden="true">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
              <circle cx="9" cy="7" r="4" />
              <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
              <path d="M16 3.13a4 4 0 0 1 0 7.75" />
            </svg>
          </span>
          <h2 className="section-title-text">Our Ministries</h2>
        </div>
        <a href="#ministries" className="section-view-all">
          <span>View All</span>
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="9 18 15 12 9 6" />
          </svg>
        </a>
      </div>

      <div className="ministries-row">
        {ministryList.map((m) => (
          <div
            key={m.id}
            className="ministry-unit-card"
            onClick={() => {
              alert(m.description || `Learn more about ${m.name} by contacting our pastoral team or joining our fellowship groups.`);
            }}
            tabIndex={0}
            role="button"
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                alert(m.description || `Learn more about ${m.name} by contacting our pastoral team.`);
              }
            }}
            aria-label={`Learn more about ${m.name}`}
          >
            <div className="ministry-photo-frame">
              <img
                src={m.photo}
                alt={m.name}
                className="ministry-photo"
                loading="lazy"
              />
            </div>
            <h3 className="ministry-label">{m.name}</h3>
          </div>
        ))}
      </div>
    </section>
  );
}

