const fs = require('fs');

const html = fs.readFileSync('dist/index.html', 'utf8');
const scriptMatch = html.match(/<script type="text\/babel">([\s\S]*?)<\/script>/);
const code = scriptMatch[1];
const lines = code.split('\n');

console.log('--- Checking all .map( calls in dist/index.html ---');
lines.forEach((line, i) => {
  const match = line.match(/([a-zA-Z0-9_]+)\.map\(/);
  if (match) {
    const varName = match[1];
    console.log(`Line ${i + 1}: ${varName}.map(...)`);
  }
});

// Check if ministryList is declared before use
const decl = lines.find(l => l.includes('const ministryList'));
const use = lines.find(l => l.includes('ministryList.map'));
console.log('Decl:', decl ? decl.trim() : 'NOT FOUND');
console.log('Use:', use ? use.trim() : 'NOT FOUND');

