65: 
66:   if (token) {
67:     headers['Authorization'] = `Bearer ${token}`;
68:   }
69: 
70:   const response = await fetch(endpoint, {
71:     ...options,
72:     headers,
73:   });
74: 
75:   if (response.status === 401) {
76:     authService.clearSession();
