  useState: (v) => [v, () => {}],
  useEffect: () => {},
  useCallback: (fn) => fn,
  useMemo: (fn) => fn(),
  useRef: () => ({ current: null }),
  createElement: (type, props, ...children) => ({ type, props, children })
};

const mockReactDOM = {
  createRoot: (el) => ({
    render: (c) => { console.log('Successfully rendered component:', typeof c.type === 'function' ? c.type.name : c.type); }
  })
};

const sandbox = {
  window: {},
  document: {
    getElementById: (id) => ({ id, appendChild: () => {} }),
    addEventListener: () => {},
    readyState: 'complete'
  },
  React: mockReact,
  ReactDOM: mockReactDOM,
  console: console,
  setTimeout: () => {}
};
sandbox.window = sandbox;

const code = fs.readFileSync('frontend/home/home.bundle.js', 'utf8');
vm.createContext(sandbox);
vm.runInContext(code, sandbox);

console.log('HomePage defined on window:', typeof sandbox.HomePage === 'function');
'''
